UPDATE admin_org_user
field_name = #{fieldName}, field_login_name = #{fieldLoginName}, field_phone = #{fieldPhone}, field_email = #{fieldEmail}, field_status = #{fieldStatus}, field_update_time = #{fieldUpdateTime}, field_lock_flag = #{fieldLockFlag}, field_unlock_time = #{fieldUnlockTime},
