SET field_last_login_time = #{fieldLoginTime}, field_last_login_ip = #{fieldLoginIp}
WHERE field_id = #{fieldId}

UPDATE admin_org_user
SET field_lock_flag = 0, field_unlock_time = NULL, field_update_time = NOW()
WHERE field_lock_flag = 1 AND field_unlock_time IS NOT NULL AND field_unlock_time <= #{now}
